    # Heuristic 2: substring "404 Not"
    if target_row is None:
        try:
            candidate = page.get_by_role("row", name="404 Not", exact=False)
            if await candidate.count() > 0:
                target_row = candidate.first
        except Exception:
            pass

    # Heuristic 3: URL key 'no-route' (common Magento 404 page identifier)
    if target_row is None:
        try:
            candidate = page.get_by_role("row", name="no-route", exact=False)
            if await candidate.count() > 0:
                target_row = candidate.first
        except Exception:
            pass

    if target_row is None:
        raise Exception('Could not find a CMS row for the 404 page (tried "404 Not Found", "404 Not", and "no-route").')

    # Inside the target row, prefer to click an edit link if present; otherwise click the first cell (Title cell)
    try:
        # Try to find a link inside the row (typical edit link lives in the title cell)
        if await target_row.get_by_role("link").count() > 0:
            edit_link = target_row.get_by_role("link").first
            await edit_link.click()
        else:
            # Fallback: click the first cell in the row (should be the Title cell)
            title_cell = target_row.get_by_role("cell").first
            await title_cell.click()
    except Exception as e:
        raise Exception(f'Failed to open the page editor from the selected row: {e}')

    # Wait for editor to load
    await page.wait_for_load_state('networkidle')

    # Locate the Page Title field and fill it
    title_locators = [
        page.get_by_role('textbox', name='Page Title', exact=True),
        page.get_by_label('Page Title'),
        page.get_by_role('textbox', name='Title', exact=True),
        page.get_by_label('Title'),
    ]

    filled = False
    for loc in title_locators:
        try:
            if await loc.count() > 0:
                await loc.first.fill('Bruh bro you clicked the wrong page')
                filled = True
                break
        except Exception:
            continue

    if not filled:
        raise Exception('Could not find the Page Title textbox in the editor to update.')

    # Click the Save button. Try common label variants; clicking Save is the final action.
    save_buttons = [
        page.get_by_role('button', name='Save Page', exact=True),
        page.get_by_role('button', name='Save', exact=True),
        page.get_by_role('button', name='Save Page', exact=False),
        page.get_by_role('button', name='Save', exact=False),
    ]

    for btn in save_buttons:
        try:
            if await btn.count() > 0:
                await btn.first.click()
                return
        except Exception:
            continue

    # If no Save button found, report error so the test author can inspect the page
    raise Exception('Could not find a Save button to save the CMS page after editing the title.')
